DROP TABLE IF EXISTS iceberg.bronze.account_wide_changed;

CREATE TABLE iceberg.bronze.account_wide_changed
WITH (format = 'PARQUET') AS
SELECT DISTINCT s.recid
FROM iceberg.bronze.account_wide_stage AS s
LEFT JOIN (SELECT DISTINCT recid, xml_hash FROM iceberg.bronze.account_wide) AS t
  ON t.recid = s.recid
WHERE t.recid IS NULL OR t.xml_hash IS DISTINCT FROM s.xml_hash;

DELETE FROM iceberg.bronze.account_wide
WHERE recid IN (SELECT recid FROM iceberg.bronze.account_wide_changed);

INSERT INTO iceberg.bronze.account_wide
SELECT s.*
FROM iceberg.bronze.account_wide_stage AS s
JOIN iceberg.bronze.account_wide_changed AS c ON c.recid = s.recid;

SELECT count(*) AS changed_records FROM iceberg.bronze.account_wide_changed;

